document.addEventListener('DOMContentLoaded',()=>{const themeBtn=document.querySelector('.theme-btn');const htmlEl=document.documentElement;const savedTheme=localStorage.getItem('theme');if(savedTheme==='dark'||(!savedTheme&&window.matchMedia('(prefers-color-scheme: dark)').matches)){htmlEl.classList.add('dark');}
if(themeBtn){themeBtn.addEventListener('click',()=>{htmlEl.classList.toggle('dark');const isDark=htmlEl.classList.contains('dark');localStorage.setItem('theme',isDark?'dark':'light');themeBtn.innerHTML=isDark?'<i class="fa-solid fa-moon"></i>':'<i class="fa-solid fa-sun"></i>';});themeBtn.innerHTML=htmlEl.classList.contains('dark')?'<i class="fa-solid fa-moon"></i>':'<i class="fa-solid fa-sun"></i>';}
const animatedElements=document.querySelectorAll('.animate-up, .animate-left, .animate-right');const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');}});},{threshold:0.1,rootMargin:'0px 0px -50px 0px'});animatedElements.forEach(el=>observer.observe(el));setTimeout(()=>{document.querySelectorAll('.hero .animate-up, .hero .animate-left, .hero .animate-right').forEach(el=>{el.classList.add('is-visible');});},100);const tabs=document.querySelectorAll('.problem-tab');const panes=document.querySelectorAll('.problem-pane');if(tabs.length>0){tabs.forEach(tab=>{tab.addEventListener('click',()=>{tabs.forEach(t=>t.classList.remove('active'));panes.forEach(p=>p.classList.remove('active'));tab.classList.add('active');const target=tab.getAttribute('data-target');const targetPane=document.getElementById(target);if(targetPane){targetPane.classList.add('active');}});});}
const opsTabs=document.querySelectorAll('.ops-tab');const opsPanes=document.querySelectorAll('.ops-pane');const opsDots=document.querySelectorAll('.ops-dot');function switchOpsTab(targetId){opsTabs.forEach(t=>t.classList.remove('active'));opsPanes.forEach(p=>p.classList.remove('active'));opsDots.forEach(d=>d.classList.remove('active'));const activeTab=document.querySelector(`.ops-tab[data-ops-target="${targetId}"]`);const activePane=document.getElementById(targetId);const activeDot=document.querySelector(`.ops-dot[data-ops-dot="${targetId}"]`);if(activeTab)activeTab.classList.add('active');if(activePane)activePane.classList.add('active');if(activeDot)activeDot.classList.add('active');}
opsTabs.forEach(tab=>{tab.addEventListener('click',()=>{switchOpsTab(tab.getAttribute('data-ops-target'));});});opsDots.forEach(dot=>{dot.addEventListener('click',()=>{switchOpsTab(dot.getAttribute('data-ops-dot'));});});const accItems=document.querySelectorAll('.svc-accordion-item');if(accItems.length>0){accItems.forEach(item=>{const header=item.querySelector('.svc-acc-header');if(header){header.addEventListener('click',()=>{item.classList.toggle('active');});}});}
const mobileMenuBtn=document.querySelector('.mobile-menu-btn');const mobileMenuOverlay=document.querySelector('.mobile-menu-overlay');if(mobileMenuBtn&&mobileMenuOverlay){mobileMenuBtn.addEventListener('click',()=>{mobileMenuOverlay.classList.toggle('active');mobileMenuBtn.classList.toggle('active');});document.addEventListener('click',(e)=>{if(mobileMenuOverlay.classList.contains('active')&&!mobileMenuOverlay.contains(e.target)&&!mobileMenuBtn.contains(e.target)){mobileMenuOverlay.classList.remove('active');mobileMenuBtn.classList.remove('active');}});}});